sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var swapAmount = parseFloat(current.getValue('requested_amount'));
    var wsdl = new x_birl3_clm.CLM_NEW_WSDL1();

    // 1. Map business segment to SAP credit segment
    function getCreditSegment(seg) {
        seg = (seg || '').trim();
        if (seg === 'Cement' || seg === 'GIL' || seg === 'BPD') return 'GIL';
        if (seg === 'RMC' || seg === 'URMX') return 'URMX';
        return 'GIL';
    }

    // 2. Fetch live Next Review Date from SAP API
    function getLiveReviewDate(custCode, salesOrg) {
        try {
            var res = wsdl.getCreditDetails(custCode, salesOrg);
            if (res) {
                var json = JSON.parse(res);
                return json.followUpDate;
            }
        } catch (e) {
            gs.error('CLM Limit Swap: Live Review Date fetch failed for ' + custCode + ': ' + e.message);
        }
        return '';
    }

    // 3. Define calculation datasets for Donor (subtract) and Donee (add)
    var parties = [{
            type: 'donor',
            code: current.getValue('donor'),
            site: current.getDisplayValue('donor'),
            salesOrg: current.donor.salesorg,
            segment: current.getValue('donor_segment') || current.donor.segment,
            newLimit: (parseFloat(current.getValue('donor_current_limit'))) - swapAmount
        },
        {
            type: 'donee',
            code: current.getValue('donee'),
            site: current.getDisplayValue('donee'),
            salesOrg: current.donee.salesorg,
            segment: current.getValue('donee_segment') || current.donee.segment + '',
            newLimit: (parseFloat(current.getValue('donee_current_limit'))) + swapAmount
        }
    ];

    // 4. Insert queue records into ServiceNow-to-SAP send-back table
    for (var i = 0; i < parties.length; i++) {
        var p = parties[i];
        var reviewDate = getLiveReviewDate(p.site, p.salesOrg);

        // Fallback to Customer Master if live API returned empty
        if (!reviewDate) {
            reviewDate = (current[p.type].next_review_date || current[p.type].u_followup_date || '') + '';
        }

        var creditSeg = getCreditSegment(p.segment);

        var q = new GlideRecord('x_birl3_clm_clm_servicenow_to_sap_send_back');
        q.initialize();

        q.setValue('nt_ls_request', current.getUniqueValue());
        q.setValue('customer_type', 'non_trade_limit_swap');
        q.setValue('u_customer_code', p.code);
        q.setValue('u_approved_code_limit', p.newLimit);
        q.setValue('u_next_review_date', reviewDate);
        q.setValue('u_credit_segment', creditSeg);
        q.setValue('u_status', 'Pending');
        q.setValue('u_attempt_count', 0);

        q.insert();
    }

})(current, previous);
